using System.Security.Claims;using Microsoft.EntityFrameworkCore;using UAF.API.Authorization;using UAF.Application.Features.Notifications;using UAF.Application.Features.Workflows;using UAF.Domain.Enums;using UAF.Infrastructure.Persistence;
namespace UAF.API.Endpoints;
public static class EnterpriseCapabilitiesEndpoints{
 public static IEndpointRouteBuilder MapEnterpriseCapabilities(this IEndpointRouteBuilder app){
 var notifications=app.MapGroup("/api/v1/notifications").WithTags("Notifications").RequireAuthorization();
 notifications.MapGet("/",async(int?page,int?pageSize,ClaimsPrincipal user,NotificationService svc,CancellationToken ct)=>{var id=Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)!);return Results.Ok(await svc.InboxAsync(id,page??1,pageSize??20,ct));}).WithName("GetMyNotifications");
 notifications.MapPatch("/{id:guid}/read",async(Guid id,ClaimsPrincipal user,NotificationService svc,CancellationToken ct)=>{await svc.MarkReadAsync(id,Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)!),ct);return Results.NoContent();}).WithName("MarkNotificationRead");
 var workflows=app.MapGroup("/api/v1/workflows").WithTags("Approval Workflows").RequireAuthorization(AuthorizationPolicies.WorkflowManagement);
 workflows.MapPost("/",async(StartWorkflowRequest r,ClaimsPrincipal user,ApprovalWorkflowService svc,CancellationToken ct)=>{var id=await svc.StartAsync(r,Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)!),ct);return Results.Created($"/api/v1/workflows/{id}/history",new{id});}).WithName("StartApprovalWorkflow");
 workflows.MapPost("/{id:guid}/approve",async(Guid id,WorkflowDecisionRequest? request,ClaimsPrincipal user,ApprovalWorkflowService svc,CancellationToken ct)=>{var actor=Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)!);var roles=user.FindAll(ClaimTypes.Role).Select(x=>x.Value);await svc.DecideAsync(id,actor,roles,true,request?.Comments,ct);return Results.NoContent();}).WithName("ApproveWorkflowStage");
 workflows.MapPost("/{id:guid}/reject",async(Guid id,WorkflowDecisionRequest request,ClaimsPrincipal user,ApprovalWorkflowService svc,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(request.Comments))return Results.BadRequest(new{error="Rejection reason required."});var actor=Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)!);var roles=user.FindAll(ClaimTypes.Role).Select(x=>x.Value);await svc.DecideAsync(id,actor,roles,false,request.Comments,ct);return Results.NoContent();}).WithName("RejectWorkflowStage");
 workflows.MapGet("/{id:guid}/history",async(Guid id,ApprovalWorkflowService svc,CancellationToken ct)=>Results.Ok(await svc.HistoryAsync(id,ct))).WithName("GetWorkflowHistory");
 app.MapGet("/api/v1/audit-trail",async(UafDbContext db,DateTimeOffset?fromUtc,DateTimeOffset?toUtc,string?entityType,Guid?entityId,int?page,int?pageSize,CancellationToken ct)=>{var q=db.AuditTrailEntries.AsNoTracking().AsQueryable();if(fromUtc.HasValue)q=q.Where(x=>x.OccurredAtUtc>=fromUtc);if(toUtc.HasValue)q=q.Where(x=>x.OccurredAtUtc<=toUtc);if(!string.IsNullOrWhiteSpace(entityType))q=q.Where(x=>x.EntityType==entityType);if(entityId.HasValue)q=q.Where(x=>x.EntityId==entityId);var p=Math.Max(1,page??1);var s=Math.Clamp(pageSize??50,1,100);return Results.Ok(await q.OrderByDescending(x=>x.OccurredAtUtc).Skip((p-1)*s).Take(s).ToListAsync(ct));}).RequireAuthorization(AuthorizationPolicies.AuditTrailRead).WithTags("Audit Trail").WithName("SearchAuditTrail");
 var search=app.MapGroup("/api/v1/search").WithTags("Search").RequireAuthorization();
 search.MapGet("/students",async(string q,int?page,int?pageSize,UafDbContext db,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(q)||q.Trim().Length<2||q.Trim().Length>100)return Results.BadRequest(new{error="Search query must contain 2 to 100 characters."});var term=q.Trim();var p=Math.Max(1,page??1);var s=Math.Clamp(pageSize??20,1,100);return Results.Ok(await db.Students.AsNoTracking().Where(x=>x.RegistrationNumber.Contains(term)||x.FullName.Contains(term)||x.Email.Contains(term)).OrderBy(x=>x.RegistrationNumber).Skip((p-1)*s).Take(s).Select(x=>new{x.Id,x.FullName,x.RegistrationNumber,x.Email}).ToListAsync(ct));}).RequireAuthorization(AuthorizationPolicies.StudentManagement).WithName("SearchStudents");
 search.MapGet("/admissions",async(string q,int?page,int?pageSize,UafDbContext db,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(q)||q.Trim().Length<2||q.Trim().Length>100)return Results.BadRequest(new{error="Search query must contain 2 to 100 characters."});var term=q.Trim();var p=Math.Max(1,page??1);var s=Math.Clamp(pageSize??20,1,100);return Results.Ok(await db.AdmissionApplications.AsNoTracking().Where(x=>x.ApplicationNumber.Contains(term)||x.ApplicantFullName.Contains(term)||x.ApplicantEmail.Contains(term)).OrderByDescending(x=>x.CreatedAtUtc).Skip((p-1)*s).Take(s).Select(x=>new{x.Id,x.ApplicationNumber,x.ApplicantFullName,x.ApplicantEmail,x.AcademicProgramId,x.Status,x.ApplicationDate}).ToListAsync(ct));}).RequireAuthorization(AuthorizationPolicies.AdmissionsStaff).WithName("SearchAdmissions");
 app.MapGet("/api/v1/analytics/dashboard",async(UafDbContext db,CancellationToken ct)=>{var students=await db.Students.CountAsync(ct);var active=await db.Students.CountAsync(x=>x.Status==StudentStatus.Active,ct);var apps=await db.AdmissionApplications.CountAsync(ct);var pending=await db.AdmissionApplications.CountAsync(x=>x.Status==AdmissionStatus.Submitted||x.Status==AdmissionStatus.UnderReview,ct);var sessions=await db.AcademicSessions.CountAsync(x=>x.Status==AcademicSessionStatus.Active,ct);var balance=await db.FeeChallans.Where(x=>x.Status!=FeeChallanStatus.Cancelled).Select(x=>x.Subtotal+x.LateFeeAmount-(db.FeePayments.Where(p=>p.ChallanId==x.Id&&p.Status==FeePaymentStatus.Verified).Sum(p=>(decimal?)p.Amount)??0m)).SumAsync(ct);return Results.Ok(new{generatedAtUtc=DateTimeOffset.UtcNow,students=new{total=students,active},admissions=new{total=apps,pending},activeAcademicSessions=sessions,finance=new{outstandingBalance=balance,currency="PKR"}});}).RequireAuthorization(AuthorizationPolicies.AnalyticsRead).WithTags("Analytics").WithName("GetDashboardAnalytics");
 return app;
 }
}
